/**
 * compiler/lower.ts — Phase 4, step 2: AST → IR (the ordering pass).
 *
 * Lowering walks the typed `Setup` and emits IR statements *in dependency order*. For a shell
 * that order is: header → environment → options → plugins → aliases → prompt init. Env comes
 * first because plugins and the prompt may read it; the prompt init comes last because it
 * depends on plugins being sourced. Sections are separated by a blank line + a comment so the
 * generated file reads like something a human wrote. Choosing this order is the lowering's job;
 * the emitter never reorders anything.
 */

import type { Setup } from './ast';
import type { ShellIR, ShellStmt, StarshipIR } from './ir';

const HEADER = 'Generated by Termi. Edit the setup, not this file.';

export function lowerShell(setup: Setup): ShellIR {
  const { shell } = setup;
  const stmts: ShellStmt[] = [{ kind: 'comment', text: HEADER }];

  const section = (title: string, items: ShellStmt[]): void => {
    if (items.length === 0) return;
    stmts.push({ kind: 'blank' }, { kind: 'comment', text: title });
    stmts.push(...items);
  };

  section(
    'Environment',
    shell.env.map((e) => ({ kind: 'export', name: e.name, value: e.value })),
  );
  section(
    'Options',
    shell.options.map((o) => ({ kind: 'option', name: o })),
  );
  section(
    'Plugins',
    shell.plugins.map((id) => ({ kind: 'plugin', id })),
  );
  section(
    'Aliases',
    shell.aliases.map((a) => ({ kind: 'alias', name: a.name, value: a.value })),
  );
  if (setup.prompt) {
    section('Prompt', [{ kind: 'initPrompt', engine: setup.prompt.engine }]);
  }

  return { shell: shell.kind, statements: stmts };
}

export function lowerPrompt(prompt: Setup['prompt']): StarshipIR | null {
  if (!prompt) return null;
  return {
    settings: [{ key: 'add_newline', value: false }],
    format: prompt.segments.map((s) => `$${s}`).join(''),
  };
}
